    /**
     * @covers AdminZone\whplugins\FakturaVydana::loadOrderData
     */
    public function testLoadOrderData()
    {
        $initial  = \Test\AbraFlexi\FakturaVydanaTest::makeTestInvoice(['firma' => 'code:VITEX']);
        $testData = ['A', 'B' => '1', 'C' => '2'];
        $result   = \AbraFlexi\Priloha::addAttachment($initial, 'order.json',
                json_encode($testData), 'application/json');
        $this->object->loadFromAbraFlexi($initial);
        $this->object->loadOrderData();
        $this->assertEquals($testData, $this->object->orderData);
    }
    
    /**
     * @covers AdminZone\whplugins\FakturaVydana::getProcessorForProduct
     */
    public function testGetProcessorForProduct()
    {
        $this->assertNull(FakturaVydana::getProcessorForProduct( new \AbraFlexi\Cenik()));
        $this->assertEquals('DomainCredit', FakturaVydana::getProcessorForProduct( new \AbraFlexi\Cenik('code:KREDIT_DOMENA') ));
        $this->assertEquals('VoIPcredit', FakturaVydana::getProcessorForProduct( new \AbraFlexi\Cenik('code:KREDIT_VOIP') ));
    }
    
